`, "",{"version":3,"sources":["webpack://./src/解语手/脚本/目标生成器/App.vue"],"names":[],"mappings":"AAgMA,SACE,mBAAoB,CACpB,0BAA2B,CAC3B,mBAAoB,CACpB,wBAAyB,CACzB,kBAAmB,CACnB,qBAAsB,CACtB,gBAAiB,CACjB,sBAAuB,CACvB,kBAAmB,CACnB,iHAAuH,CACvH,2CAA+C,CAE/C,UAAW,CACX,eAAgB,CAChB,iBAAkB,CAClB,4BAA6B,CAC7B,cAAe,CACf,eAAgB,CAChB,mBAAoB,CACpB,eACF,CAEA,gDAGE,qBACF","sourcesContent":["<template>\n  <div class=\"inner\">\n    <header class=\"bar\" @click=\"ui.toggleExpanded()\">\n      <span class=\"tube\" aria-hidden=\"true\">签</span>\n      <span class=\"title\">客源</span>\n      <span class=\"summary\">{{ summary }}</span>\n      <span v-if=\"rosterCount\" class=\"badge\">名册 {{ rosterCount }}</span>\n      <span class=\"flip\">{{ ui.expanded ? '收起' : '展开' }}</span>\n    </header>\n\n    <Transition name=\"unfold\">\n      <div v-if=\"ui.expanded\" class=\"body\">\n        <div class=\"field\">\n          <span class=\"field-label\">职业池</span>\n          <PoolChips v-model=\"ui.pools\" />\n        </div>\n\n        <div class=\"field\">\n          <span class=\"field-label\">年龄段</span>\n          <AgeChips v-model=\"ui.ageIndex\" />\n        </div>\n\n        <div class=\"tabs\">\n          <button\n            v-for=\"tab in TABS\"\n            :key=\"tab.value\"\n            type=\"button\"\n            class=\"tab\"\n            :class=\"{ 'is-on': mode === tab.value }\"\n            @click=\"mode = tab.value\"\n          >\n            {{ tab.label }}\n          </button>\n        </div>\n\n        <template v-if=\"mode === '自约'\">\n          <div class=\"draw\">\n            <button type=\"button\" class=\"btn btn-primary\" @click=\"draw\">掷一支签</button>\n            <span v-if=\"!ui.slip\" class=\"hint\">签筒里装的是这座城里各式各样的女人。</span>\n          </div>\n        </template>\n\n        <template v-else>\n          <p v-if=\"!referrer\" class=\"hint\">先在下面的名册里挑一位熟客，让她带朋友来。</p>\n          <p v-else class=\"picked\">\n            让 <b>{{ referrer }}</b> 带一位朋友来\n            <button type=\"button\" class=\"link\" @click=\"referrer = ''\">换一位</button>\n          </p>\n          <div class=\"draw\">\n            <button type=\"button\" class=\"btn btn-primary\" :disabled=\"!referrer\" @click=\"draw\">让她带朋友来</button>\n          </div>\n        </template>\n\n        <GuestSlip\n          v-if=\"ui.slip\"\n          :guest=\"ui.slip\"\n          :scene=\"ui.scene\"\n          @adopt=\"adopt\"\n          @redraw=\"draw\"\n          @update:scene=\"value => (ui.scene = value)\"\n        />\n\n        <RosterPanel :roster=\"roster\" @refer=\"pickReferrer\" @hand-over=\"handOver\" />\n      </div>\n    </Transition>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport AgeChips from './components/AgeChips.vue';\nimport GuestSlip from './components/GuestSlip.vue';\nimport PoolChips from './components/PoolChips.vue';\nimport RosterPanel from './components/RosterPanel.vue';\nimport { AGE_BANDS, asSelfBooked, drawGuest, drawReferredGuest } from './data';\nimport { buildOpeningText } from './narrative';\nimport {\n  adoptGuest,\n  archiveCurrentGuest,\n  handRosterToNarrator,\n  linkReferral,\n  putTextIntoInput,\n  takenNames,\n  useRoster,\n  useStatData,\n  useUiStore,\n} from './store';\n\nconst TABS = [\n  { value: '自约' as const, label: '掷签 · 新客自己预约' },\n  { value: '引荐' as const, label: '熟人引荐 · 她带朋友来' },\n];\n\nconst ui = useUiStore();\nconst { statData, reload } = useStatData();\nconst { roster, reload: reloadRoster } = useRoster();\n\nconst mode = ref<'自约' | '引荐'>('自约');\nconst referrer = ref('');\nconst shaking = ref(false);\n\nconst currentName = computed(() => String(_.get(statData.value, '当前客人.姓名', '') ?? ''));\nconst rosterCount = computed(() => Object.keys(roster.value).length);\n\nconst summary = computed(() => {\n  if (currentName.value) {\n    return `店里 · ${currentName.value}`;\n  }\n  return '还没有客人';\n});\n\nconst pickReferrer = (name: string) => {\n  referrer.value = name;\n  mode.value = '引荐';\n  ui.expanded = true;\n};\n\n/** 掷签或让熟人引荐，两位都由这里产生 */\nconst draw = () => {\n  const taken = takenNames(statData.value, roster.value);\n  const ageRange = AGE_BANDS[ui.ageIndex]?.range ?? null;\n\n  let guest;\n  if (mode.value === '引荐') {\n    if (!referrer.value) {\n      toastr.warning('先在名册里挑一位熟客', '客源');\n      return;\n    }\n    const entry = roster.value[referrer.value];\n    guest = drawReferredGuest({\n      pools: ui.pools,\n      ageRange,\n      taken,\n      referrer: { 姓名: referrer.value, pool: entry?.圈层, 知情: entry?.关系状态 === '情人' },\n    });\n  } else {\n    const drawn = drawGuest({ pools: ui.pools, ageRange, taken });\n    guest = drawn ? asSelfBooked(drawn) : null;\n  }\n\n  if (!guest) {\n    toastr.warning('这一类里没有合年纪的人，放宽些再抽', '客源');\n    return;\n  }\n\n  shaking.value = true;\n  window.setTimeout(() => {\n    ui.slip = guest;\n    shaking.value = false;\n  }, 420);\n};\n\nconst adopt = () => {\n  if (!ui.slip) {\n    return;\n  }\n  const guest = ui.slip;\n\n  // 换人前先把上位客人归档\n  const archived = archiveCurrentGuest(statData.value);\n  adoptGuest(guest, ui.scene);\n\n  // 引荐链：把新客人记进引荐人的「带过的人」\n  if (guest.来路 === '熟人引荐' && guest.引荐人) {\n    linkReferral(guest.引荐人, guest.姓名);\n  }\n\n  const ok = putTextIntoInput(buildOpeningText(guest));\n\n  ui.slip = null;\n  ui.expanded = false;\n  referrer.value = '';\n  reload();\n  reloadRoster();\n\n  const head = archived ? `已把 ${archived} 记进名册，${guest.姓名} 立为新客` : `已请 ${guest.姓名} 进来`;\n  if (ok) {\n    toastr.success(`${head}；话已放进输入栏，看过再发`, '客源');\n  } else {\n    toastr.warning(`${head}；但没找到输入栏，话没能自动填入`, '客源');\n  }\n};\n\nconst handOver = () => {\n  if (handRosterToNarrator(roster.value)) {\n    toastr.success('名册已放进输入框，按你的意思发出去', '客源');\n    return;\n  }\n  toastr.warning('名册还空着', '客源');\n};\n</script>\n\n<style>\n#jy-dock {\n  --c-surface: #f4f6f5;\n  --c-surface-raised: #ffffff;\n  --c-primary: #35606a;\n  --c-primary-soft: #8fadb3;\n  --c-accent: #b0645f;\n  --c-secondary: #b8823c;\n  --c-text: #23302f;\n  --c-text-muted: #7c8a88;\n  --c-border: #d5dddb;\n  --font-body: 'PingFang SC', 'Hiragino Sans GB', 'Source Han Sans SC', 'Noto Sans CJK SC', 'Microsoft YaHei', sans-serif;\n  --ease-gentle: cubic-bezier(0.33, 0.9, 0.35, 1);\n\n  width: 100%;\n  max-width: 780px;\n  margin: 0 auto 4px;\n  font-family: var(--font-body);\n  font-size: 12px;\n  line-height: 1.5;\n  color: var(--c-text);\n  text-align: left;\n}\n\n#jy-dock *,\n#jy-dock *::before,\n#jy-dock *::after {\n  box-sizing: border-box;\n}\n</style>\n\n<style lang=\"scss\" scoped>\n.inner {\n  border: 1px solid var(--c-border);\n  border-radius: 2px;\n  background: var(--c-surface);\n  overflow: hidden;\n}\n\n.bar {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 4px 9px;\n  cursor: pointer;\n  user-select: none;\n}\n\n.bar:hover {\n  background: rgba(53, 96, 106, 0.07);\n}\n\n.tube {\n  flex: 0 0 auto;\n  width: 18px;\n  height: 18px;\n  line-height: 18px;\n  text-align: center;\n  font-size: 11px;\n  color: var(--c-surface-raised);\n  background: var(--c-primary);\n  border-radius: 2px;\n}\n\n.title {\n  font-size: 12px;\n  letter-spacing: 2px;\n  color: var(--c-primary);\n  white-space: nowrap;\n}\n\n.summary {\n  flex: 1;\n  min-width: 0;\n  font-size: 11px;\n  color: var(--c-text-muted);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.badge {\n  flex: 0 0 auto;\n  font-size: 10px;\n  color: var(--c-primary);\n  border: 1px solid var(--c-primary-soft);\n  padding: 0 5px;\n}\n\n.flip {\n  flex: 0 0 auto;\n  font-size: 11px;\n  color: var(--c-primary-soft);\n}\n\n.body {\n  padding: 8px 9px 9px;\n  border-top: 1px solid var(--c-border);\n  display: flex;\n  flex-direction: column;\n  gap: 7px;\n}\n\n.field {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.field-label {\n  flex: 0 0 auto;\n  font-size: 11px;\n  letter-spacing: 1px;\n  color: var(--c-text-muted);\n}\n\n.tabs {\n  display: flex;\n  gap: 4px;\n}\n\n.tab {\n  font-family: inherit;\n  font-size: 11.5px;\n  padding: 3px 12px;\n  letter-spacing: 1px;\n  color: var(--c-text-muted);\n  background: transparent;\n  border: 1px solid var(--c-border);\n  border-radius: 2px;\n  cursor: pointer;\n}\n\n.tab.is-on {\n  color: var(--c-surface-raised);\n  background: var(--c-primary);\n  border-color: var(--c-primary);\n}\n\n.draw {\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  flex-wrap: wrap;\n}\n\n.hint {\n  font-size: 10.5px;\n  color: var(--c-text-muted);\n}\n\n.picked {\n  font-size: 11.5px;\n  color: var(--c-text);\n}\n\n.picked b {\n  color: var(--c-primary);\n}\n\n.link {\n  margin-left: 6px;\n  padding: 0;\n  border: none;\n  background: transparent;\n  font-family: inherit;\n  font-size: 10.5px;\n  color: var(--c-primary-soft);\n  border-bottom: 1px dashed var(--c-primary-soft);\n  cursor: pointer;\n}\n\n.btn {\n  font-family: inherit;\n  font-size: 11.5px;\n  padding: 3px 14px;\n  letter-spacing: 1px;\n  color: var(--c-primary);\n  background: var(--c-surface-raised);\n  border: 1px solid var(--c-primary-soft);\n  border-radius: 2px;\n  cursor: pointer;\n}\n\n.btn:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n\n.btn-primary {\n  color: var(--c-surface-raised);\n  background: var(--c-primary);\n  border-color: var(--c-primary);\n}\n\n.unfold-enter-active,\n.unfold-leave-active {\n  transition: opacity 220ms var(--ease-gentle);\n  overflow: hidden;\n}\n\n.unfold-enter-from,\n.unfold-leave-to {\n  opacity: 0;\n}\n</style>"],"sourceRoot":""}]);
